// ============================================================
// PARSE MENSAGEM - Evolution API
// ============================================================
const body = $input.first().json.body || $input.first().json;

// Suporte a Evolution API v1 e v2
const data = body.data || body;
const key = data.key || {};
const fromMe = key.fromMe || false;

// Ignorar mensagens enviadas pelo bot
if (fromMe) return [];

// Extrair telefone e mensagem
const remoteJid = key.remoteJid || data.from || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
const pushName = data.pushName || data.notifyName || 'Cliente';

const message = (
  data.message?.conversation ||
  data.message?.extendedTextMessage?.text ||
  data.message?.buttonsResponseMessage?.selectedDisplayText ||
  data.message?.listResponseMessage?.title ||
  body.text ||
  ''
).trim().toLowerCase();

if (!phone || !message) return [];

return [{ json: { phone, pushName, message, rawBody: body } }];

// ============================================================
// GERENCIADOR DE SESSÃO + LÓGICA DO BOT
// ============================================================
// Sessões ficam salvas entre execuções via staticData
const sessions = $workflow.staticData.sessions || {};

const { phone, pushName, message } = $input.first().json;

// Obter ou criar sessão
let session = sessions[phone] || { state: 'INICIO', cart: [], nome: '', telefone: phone };

// Comandos globais (funcionam em qualquer estado)
if (['cancelar', 'sair', 'menu', 'inicio', '0'].includes(message)) {
  session = { state: 'INICIO', cart: [], nome: '', telefone: phone };
}

let responseText = '';
let action = 'send_text'; // send_text | fetch_menu | create_order

// ============================================================
// MÁQUINA DE ESTADOS
// ============================================================
switch (session.state) {

  case 'INICIO': {
    responseText = `Olá, ${pushName}! 👋\n\n🍔 *Bem-vindo à Neuzalanches!*\n\nO que você deseja?\n\n1️⃣ Ver cardápio e fazer pedido\n2️⃣ Falar com atendente\n\n_Digite o número da opção_`;
    session.state = 'AGUARDANDO_OPCAO';
    break;
  }

  case 'AGUARDANDO_OPCAO': {
    if (message === '1' || message.includes('cardápio') || message.includes('cardapio') || message.includes('pedido')) {
      action = 'fetch_menu';
      session.state = 'MENU';
    } else if (message === '2' || message.includes('atendente') || message.includes('humano')) {
      responseText = '👤 Transferindo para um atendente...\n\nAguarde um momento que já te atendemos! 😊';
      session.state = 'INICIO';
    } else {
      responseText = 'Por favor, digite *1* para ver o cardápio ou *2* para falar com atendente.';
    }
    break;
  }

  case 'MENU': {
    // Esta parte será preenchida após buscar o cardápio
    // Redirecionar para buscar cardápio de novo se necessário
    action = 'fetch_menu';
    break;
  }

  case 'SELECIONANDO': {
    const num = parseInt(message);
    const produtos = session.produtos || [];

    if (message === 'ver carrinho' || message === 'carrinho') {
      if (session.cart.length === 0) {
        responseText = '🛒 Seu carrinho está vazio.\n\nDigite o número de um item para adicionar.';
      } else {
        const total = session.cart.reduce((s, i) => s + i.preco * i.qty, 0);
        const itens = session.cart.map(i => `  • ${i.qty}x ${i.nome} — R$ ${(i.preco * i.qty).toFixed(2)}`).join('\n');
        responseText = `🛒 *Seu carrinho:*\n\n${itens}\n\n*Total: R$ ${total.toFixed(2)}*\n\n✅ Digite *confirmar* para fechar o pedido\n➕ Ou continue adicionando itens\n🔄 Digite *cancelar* para recomeçar`;
      }
    } else if (message === 'confirmar' || message === 'fechar pedido') {
      if (session.cart.length === 0) {
        responseText = '⚠️ Adicione pelo menos um item antes de confirmar.';
      } else {
        responseText = `✏️ Para finalizar, preciso de alguns dados.\n\nQual é o seu *nome completo*?`;
        session.state = 'COLETANDO_NOME';
      }
    } else if (!isNaN(num) && num >= 1 && num <= produtos.length) {
      const produto = produtos[num - 1];
      const existing = session.cart.find(i => i.produto_id === produto.id);
      if (existing) {
        existing.qty++;
      } else {
        session.cart.push({ produto_id: produto.id, nome: produto.nome, preco: produto.preco, qty: 1 });
      }
      const total = session.cart.reduce((s, i) => s + i.preco * i.qty, 0);
      responseText = `✅ *${produto.nome}* adicionado!\n\n🛒 ${session.cart.reduce((s,i)=>s+i.qty,0)} item(ns) — R$ ${total.toFixed(2)}\n\nDigite outro número para adicionar mais,\n*ver carrinho* para ver os itens ou\n*confirmar* para fechar o pedido.`;
    } else {
      responseText = `Opção inválida. Digite o *número* do item, *ver carrinho* ou *confirmar*.`;
    }
    break;
  }

  case 'COLETANDO_NOME': {
    if (message.length < 3) {
      responseText = 'Por favor, informe seu *nome completo*.';
    } else {
      session.nome = pushName !== 'Cliente' && message.length < 4 ? pushName : message.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
      responseText = `Obrigado, *${session.nome}*! 😊\n\nQual o seu número de *WhatsApp* para contato?\n_(com DDD, ex: 11999998888)_`;
      session.state = 'COLETANDO_TELEFONE';
    }
    break;
  }

  case 'COLETANDO_TELEFONE': {
    const tel = message.replace(/\D/g, '');
    if (tel.length < 10 || tel.length > 11) {
      responseText = 'Por favor, informe um número válido com DDD.\nEx: *11999998888*';
    } else {
      session.telefoneContato = tel;
      responseText = `📍 Qual o *tipo de entrega*?\n\n1️⃣ Entrega no endereço\n2️⃣ Retirada no local`;
      session.state = 'COLETANDO_TIPO';
    }
    break;
  }

  case 'COLETANDO_TIPO': {
    if (message === '1' || message.includes('entrega') || message.includes('endereço') || message.includes('endereco')) {
      session.tipo = 'entrega';
      responseText = `🏠 Qual o *CEP* para entrega?\n_(apenas números, ex: 01310100)_`;
      session.state = 'COLETANDO_CEP';
    } else if (message === '2' || message.includes('retira') || message.includes('local') || message.includes('buscar')) {
      session.tipo = 'retirada';
      responseText = `💳 *Forma de pagamento:*\n\n1️⃣ PIX\n2️⃣ Dinheiro\n3️⃣ Cartão na entrega`;
      session.state = 'COLETANDO_PAGAMENTO';
    } else {
      responseText = 'Digite *1* para entrega ou *2* para retirada no local.';
    }
    break;
  }

  case 'COLETANDO_CEP': {
    const cep = message.replace(/\D/g, '');
    if (cep.length !== 8) {
      responseText = 'CEP inválido. Por favor, informe o CEP com 8 dígitos.\nEx: *01310100*';
    } else {
      session.endereco = session.endereco || {};
      session.endereco.cep = cep;
      responseText = `📍 Qual o *nome da rua/avenida*?`;
      session.state = 'COLETANDO_RUA';
    }
    break;
  }

  case 'COLETANDO_RUA': {
    if (message.length < 3) {
      responseText = 'Por favor, informe o nome da rua.';
    } else {
      session.endereco.rua = message;
      responseText = `Qual o *número* do endereço?`;
      session.state = 'COLETANDO_NUMERO';
    }
    break;
  }

  case 'COLETANDO_NUMERO': {
    session.endereco.numero = message;
    responseText = `Qual o *bairro*?`;
    session.state = 'COLETANDO_BAIRRO';
    break;
  }

  case 'COLETANDO_BAIRRO': {
    if (message.length < 2) {
      responseText = 'Por favor, informe o bairro.';
    } else {
      session.endereco.bairro = message;
      responseText = `Algum *ponto de referência*? (ou digite *não* para pular)`;
      session.state = 'COLETANDO_REFERENCIA';
    }
    break;
  }

  case 'COLETANDO_REFERENCIA': {
    session.endereco.referencia = (message === 'não' || message === 'nao') ? '' : message;
    responseText = `💳 *Forma de pagamento:*\n\n1️⃣ PIX\n2️⃣ Dinheiro\n3️⃣ Cartão na entrega`;
    session.state = 'COLETANDO_PAGAMENTO';
    break;
  }

  case 'COLETANDO_PAGAMENTO': {
    let metodoPagamento = '';
    if (message === '1' || message.includes('pix')) {
      metodoPagamento = 'pix';
    } else if (message === '2' || message.includes('dinheiro')) {
      metodoPagamento = 'dinheiro';
    } else if (message === '3' || message.includes('cartão') || message.includes('cartao') || message.includes('card')) {
      metodoPagamento = 'cartao';
    } else {
      responseText = 'Digite *1* para PIX, *2* para Dinheiro ou *3* para Cartão.';
      break;
    }
    session.metodoPagamento = metodoPagamento;

    // Montar resumo do pedido
    const total = session.cart.reduce((s, i) => s + i.preco * i.qty, 0);
    const itens = session.cart.map(i => `  • ${i.qty}x ${i.nome} — R$ ${(i.preco * i.qty).toFixed(2)}`).join('\n');
    const enderecoStr = session.tipo === 'entrega' && session.endereco
      ? `\n📍 *Endereço:* ${session.endereco.rua}, ${session.endereco.numero} — ${session.endereco.bairro} (CEP: ${session.endereco.cep})`
      : '\n🏪 *Retirada no local*';
    const pagStr = metodoPagamento === 'pix' ? 'PIX' : metodoPagamento === 'dinheiro' ? 'Dinheiro' : 'Cartão';

    responseText = `📋 *Resumo do pedido:*\n\n${itens}\n\n💰 *Total: R$ ${total.toFixed(2)}*\n💳 *Pagamento:* ${pagStr}${enderecoStr}\n\n✅ Digite *confirmar* para enviar o pedido\n❌ Digite *cancelar* para recomeçar`;
    session.state = 'CONFIRMANDO';
    break;
  }

  case 'CONFIRMANDO': {
    if (message === 'confirmar') {
      action = 'create_order';
    } else if (message === 'cancelar') {
      session = { state: 'INICIO', cart: [], nome: '', telefone: phone };
      responseText = '❌ Pedido cancelado.\n\nDigite *oi* para começar novamente!';
    } else {
      responseText = 'Digite *confirmar* para enviar ou *cancelar* para recomeçar.';
    }
    break;
  }

  default: {
    session.state = 'INICIO';
    responseText = 'Olá! 👋 Digite *oi* para ver nosso cardápio.';
  }
}

// Salvar sessão
sessions[phone] = session;
$workflow.staticData.sessions = sessions;

return [{
  json: {
    phone,
    responseText,
    action,
    session
  }
}];

// Formatar cardápio para WhatsApp
const produtos = $input.first().json;
const botData = $('Lógica do Bot').first().json;
const sessions = $workflow.staticData.sessions || {};
const session = sessions[botData.phone] || {};

// Agrupar por categoria
const categorias = {};
produtos.forEach((p, i) => {
  const cat = p.categoria || 'Outros';
  if (!categorias[cat]) categorias[cat] = [];
  categorias[cat].push({ ...p, index: i + 1 });
});

// Salvar produtos na sessão para referência
session.produtos = produtos;
session.state = 'SELECIONANDO';
sessions[botData.phone] = session;
$workflow.staticData.sessions = sessions;

// Montar mensagem
let msg = `🍔 *CARDÁPIO NEUZALANCHES* 🍔\n\n`;
let counter = 1;
const allProducts = [];

Object.entries(categorias).forEach(([cat, items]) => {
  msg += `*${cat.toUpperCase()}*\n`;
  items.forEach(p => {
    msg += `${counter}️⃣ ${p.nome} — R$ ${parseFloat(p.preco).toFixed(2)}\n`;
    allProducts.push(p);
    counter++;
  });
  msg += '\n';
});

msg += `_Digite o *número* do item para adicionar ao carrinho_\n`;
msg += `_Digite *ver carrinho* para ver o pedido_\n`;
msg += `_Digite *confirmar* para fechar o pedido_`;

return [{ json: { phone: botData.phone, responseText: msg } }];

