// Formatar confirmação do pedido
const pedido = $input.first().json;
const botData = $('Lógica do Bot').first().json;
const sessions = $workflow.staticData.sessions || {};

// Limpar sessão após pedido confirmado
const session = sessions[botData.phone] || {};
const nome = session.nome || 'Cliente';
const total = (session.cart || []).reduce((s, i) => s + i.preco * i.qty, 0);
const metodoPag = session.metodoPagamento || '';

// Reset da sessão
sessions[botData.phone] = { state: 'INICIO', cart: [], nome: '', telefone: botData.phone };
$workflow.staticData.sessions = sessions;

let pixInfo = '';
if (metodoPag === 'pix') {
  pixInfo = `\n\n💳 *Chave PIX:* (configure na plataforma)\nFavor enviar o comprovante após o pagamento.`;
}

const msg = `🎉 *Pedido confirmado, ${nome}!*\n\n📋 *Pedido #${pedido.id || 'N/A'}*\n💰 *Total: R$ ${total.toFixed(2)}*${pixInfo}\n\n⏱️ Tempo estimado: 30-45 minutos\n\nObrigado por escolher a Neuzalanches! 🍔❤️\n\n_Digite *oi* para fazer outro pedido_`;

return [{ json: { phone: botData.phone, responseText: msg } }];
